67],[43.209974,-5.667774],[43.21003,-5.667613],[43.210039,-5.66745],[43.209975,-5.667308],[43.209917,-5.667129],[43.209828,-5.666941],[43.209801,-5.66681],[43.209806,-5.666681],[43.209843,-5.666507],[43.209891,-5.666351],[43.209965,-5.666198],[43.210012,-5.666037],[43.210137,-5.665634],[43.21021,-5.665213],[43.210286,-5.664987],[43.210415,-5.664805],[43.21046,-5.66474],[43.210627,-5.664596],[43.21069,-5.664393],[43.210658,-5.664209],[43.210626,-5.664037],[43.210583,-5.663916],[43.210535,-5.663824],[43.21047,-5.663665],[43.210408,-5.663436],[43.210395,-5.663289],[43.210451,-5.663035],[43.210486,-5.662832],[43.210491,-5.662682],[43.210488,-5.662556],[43.210514,-5.662485],[43.210595,-5.662358],[43.210724,-5.662202],[43.210818,-5.662049],[43.210879,-5.661905],[43.210928,-5.661733],[43.211048,-5.66159],[43.211195,-5.661487],[43.211397,-5.66134],[43.211594,-5.661277],[43.211733,-5.661211],[43.211847,-5.661105],[43.21193,-5.660981],[43.211962,-5.660823],[43.211991,-5.660561],[43.21204,-5.660227],[43.212119,-5.659689],[43.212191,-5.659325],[43.212261,-5.659108],[43.212332,-5.658951],[43.212379,-5.658797],[43.212423,-5.6586],[43.212408,-5.658479],[43.212391,-5.658335],[43.212317,-5.658114],[43.212267,-5.657916],[43.212262,-5.657783],[43.212272,-5.657526],[43.212344,-5.657268],[43.212487,-5.656802],[43.212509,-5.656659],[43.212524,-5.656526],[43.212539,-5.656205],[43.212517,-5.655664],[43.212522,-5.655506],[43.212541,-5.655454],[43.212541,-5.655454],[43.212541,-5.655454]]$coords$::jsonb;
  v_route record;
  v_points jsonb;
  v_count integer;
  v_length_km double precision;
  v_max_gap_km double precision;
  v_center_gap_km double precision;
  v_invalid integer;
  v_start_gap_m double precision;
  v_end_gap_m double precision;
begin
  select h.id,h.latitude,h.longitude,t.status,t.geometry_source_url
    into v_route
    from public.hiking_routes h
    join public.hiking_route_tracks t on t.route_id=h.id
    where h.id='osm-relation-3739479'
      and h.source='openstreetmap'
      and h.name='Vía Verde del Valle de Turón'
      and h.raw_tags->>'ref'='PR-AS 100.1'
      and h.official_url in (
        'https://www.viasverdes.com/itinerarios/itinerario.asp?id=29',
        'https://viasverdes.com/itinerarios/valle-del-turon/'
      )
      and exists (select 1 from public.hiking_route_regions r
        where r.route_id=h.id and r.region_code='asturias' and r.published);
  if not found then
    raise exception 'Valle del Turón route identity or published region changed';
  end if;
  if v_route.status='ready' then
    if v_route.geometry_source_url='https://rutas.viasverdes.com/cgmlformfilewd/845-aumxnyb/TURO_VVValleTuron.gpx' then
      return;
    end if;
    raise exception 'Valle del Turón route has another ready trace';
  end if;
  if v_route.status<>'missing' then
    raise exception 'Valle del Turón status changed: %',v_route.status;
  end if;

  with points as (
    select ordinality idx,(point->>0)::double precision lat,
      (point->>1)::double precision lon
    from jsonb_array_elements(v_coords) with ordinality as p(point,ordinality)
  ), steps as (
    select *,lag(lat) over(order by idx) prev_lat,
      lag(lon) over(order by idx) prev_lon from points
  ), distances as (
    select case when prev_lat is null then 0 else
      ST_DistanceSphere(ST_MakePoint(lon,lat),
        ST_MakePoint(prev_lon,prev_lat))/1000 end step_km,
      ST_DistanceSphere(ST_MakePoint(lon,lat),
        ST_MakePoint(v_route.longitude,v_route.latitude))/1000 center_km,
      (lat between 27 and 45 and lon between -19 and 5) valid
    from steps
  )
  select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
    coalesce(min(center_km),999),count(*) filter(where not valid)
    into v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid
    from distances;

  select ST_DistanceSphere(
    ST_MakePoint((v_coords->0->>1)::double precision,(v_coords->0->>0)::double precision),
    ST_MakePoint(-5.786874274,43.210980374)),
    ST_DistanceSphere(
    ST_MakePoint((v_coords->(v_count-1)->>1)::double precision,
      (v_coords->(v_count-1)->>0)::double precision),
    ST_MakePoint(-5.655454465,43.212541162))
    into v_start_gap_m,v_end_gap_m;

  if v_count<>618 or v_invalid>0
    or abs(v_length_km-12.933)>0.03
    or v_max_gap_km>0.16 or v_center_gap_km>0.6
    or v_start_gap_m>2 or v_end_gap_m>2 then
    raise exception 'Valle del Turón GPS validation failed: points %, length %, gap %, center %, start %, end %, invalid %',
      v_count,v_length_km,v_max_gap_km,v_center_gap_km,
      v_start_gap_m,v_end_gap_m,v_invalid;
  end if;

  select jsonb_agg(jsonb_build_object(
    'lat',(point->>0)::double precision,
    'lon',(point->>1)::double precision
  ) order by ordinality)
    into v_points
    from jsonb_array_elements(v_coords)
      with ordinality as p(point,ordinality);

  insert into public.hiking_route_tracks
    (route_id,status,segments,checked_at,continuity_checked,
     geometry_source,geometry_source_url,official)
  values (
    v_route.id,'ready',jsonb_build_array(v_points),now(),true,
    'Fundación de los Ferrocarriles Españoles - GPX oficial',
    'https://rutas.viasverdes.com/cgmlformfilewd/845-aumxnyb/TURO_VVValleTuron.gpx',true
  )
  on conflict(route_id) do update set
    status=excluded.status,segments=excluded.segments,
    checked_at=excluded.checked_at,continuity_checked=true,
    geometry_source=excluded.geometry_source,
    geometry_source_url=excluded.geometry_source_url,official=true;

  update public.hiking_routes
    set trace_available=true,published=true,
      distance_km=round(v_length_km::numeric,2),route_type='Lineal',
      official_url='https://viasverdes.com/itinerarios/valle-del-turon/',
      description='Vía Verde del Valle del Turón, tramo oficial de 12,96 km desde el viaducto de Ricastro (Uxo) hasta La Molinera (Güeria d’Urbiés). El trazado descargable termina en La Molinera; la variante hasta El Mosquil figura en otra ficha turística. Atención en túneles sin iluminación y cruces de carretera.'
    where id=v_route.id and not published and not trace_available;
  if not found then
    raise exception 'Valle del Turón publication state changed';
  end if;
end
$curate$;
